#!/usr/bin/env node
import browserslist from "browserslist";
const ES_VERSIONS_MAP = {
    chrome: [
        51,
        52,
        57,
        64,
        73,
        80,
        85,
        94,
        110,
        119
    ],
    edge: [
        15,
        15,
        15,
        79,
        79,
        80,
        85,
        94,
        110,
        119
    ],
    safari: [
        10,
        10.3,
        11,
        16.4,
        17,
        17,
        17,
        17,
        17,
        17.4
    ],
    firefox: [
        54,
        54,
        54,
        78,
        78,
        80,
        80,
        93,
        115,
        145
    ],
    opera: [
        38,
        39,
        44,
        51,
        60,
        67,
        71,
        80,
        96,
        105
    ],
    samsung: [
        5,
        6.2,
        6.2,
        8.2,
        11.1,
        13,
        14,
        17,
        21,
        25
    ]
};
const aliases = {
    ios_saf: 'safari',
    and_chr: 'chrome',
    and_ff: 'firefox'
};
const renameBrowser = (name)=>aliases[name] || name;
function browsersToESVersion(browsers) {
    let esVersion = 2024;
    for (const item of browsers){
        const pairs = item.split(' ');
        if (pairs.length < 2) continue;
        const browser = renameBrowser(pairs[0]);
        const version = Number(pairs[1].split('-')[0]);
        if (Number.isNaN(version)) continue;
        if ('ie' === browser || 'android' === browser && version < 6) {
            esVersion = 5;
            break;
        }
        const versions = ES_VERSIONS_MAP[browser];
        if (versions) {
            if (version < versions[0]) esVersion = Math.min(5, esVersion);
            else if (version < versions[1]) esVersion = Math.min(2015, esVersion);
            else if (version < versions[2]) esVersion = Math.min(2016, esVersion);
            else if (version < versions[3]) esVersion = Math.min(2017, esVersion);
            else if (version < versions[4]) esVersion = Math.min(2018, esVersion);
            else if (version < versions[5]) esVersion = Math.min(2019, esVersion);
            else if (version < versions[6]) esVersion = Math.min(2020, esVersion);
            else if (version < versions[7]) esVersion = Math.min(2021, esVersion);
            else if (version < versions[8]) esVersion = Math.min(2022, esVersion);
            else if (version < versions[9]) esVersion = Math.min(2023, esVersion);
        }
    }
    return esVersion;
}
function browserslistToESVersion(browsers) {
    const projectBrowsers = browserslist(browsers, {
        ignoreUnknownVersions: true
    });
    return browsersToESVersion(projectBrowsers);
}
const args = process.argv.slice(2);
if (args.includes('--help') || args.includes('-h')) {
    console.log(`
browserslist-to-es-version

Usage:
  npx browserslist-to-es-version [query]

Arguments:
  query    Optional browserslist query (default: reads from local config)

Examples:
  npx browserslist-to-es-version
  npx browserslist-to-es-version "Chrome >= 80, Firefox >= 72"
`);
    process.exit(0);
}
try {
    let browsers;
    if (args.length > 0) browsers = browserslist(args.join(' '));
    else {
        const configFile = browserslist.findConfigFile('.');
        if (!configFile) {
            console.error('Error: No browserslist configuration found.\n\nCreate a .browserslistrc file or add a "browserslist" field to package.json.\nAlternatively, provide a query as an argument:\n  npx browserslist-to-es-version "Chrome >= 80, Firefox >= 72"');
            process.exit(1);
        }
        browsers = browserslist();
    }
    const esVersion = browserslistToESVersion(browsers);
    console.log(esVersion);
} catch (error) {
    console.error('Error:', error instanceof Error ? error.message : String(error));
    process.exit(1);
}
